contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address other) public {
        require(other != address(this));

        uint beforeThis = c.tokenBalance(address(this));
        uint beforeOther = c.tokenBalance(other);

        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterThis = c.tokenBalance(address(this));
        uint afterOther = c.tokenBalance(other);

        if (!reverted) {
            assert(afterThis == beforeThis + 20 && afterOther == beforeOther);
        } else {
            assert(beforeThis != 0 || afterThis != beforeThis + 20 || afterOther != beforeOther);
        }
    }
}

