contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public {
        // First call: caller has no balance, so becomes 20.
        c.airDrop();
        uint afterFirst = c.tokenBalance(address(this));
        require(afterFirst == 20);

        // Second call: caller now has a balance, so must revert.
        bool reverted;
        try c.airDrop() { reverted = true; } catch { reverted = false; }

        uint afterSecond = c.tokenBalance(address(this));

        assert(reverted == false && afterSecond == 20);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint initialFlag) public {
        // Ensure the test starts with zero balance for this contract.
        // The shared contract c is fresh per deployment, so this is always true,
        // but we use the parameter only to satisfy the shape requirement.
        require(initialFlag == 0);

        uint before = c.tokenBalance(address(this));

        // First airDrop: must succeed and set balance to 20.
        bool firstReverted;
        try c.airDrop() { firstReverted = false; } catch { firstReverted = true; }

        uint afterFirst = c.tokenBalance(address(this));

        // Second airDrop: must revert because balance is now 20 (not zero).
        bool secondReverted;
        try c.airDrop() { secondReverted = false; } catch { secondReverted = true; }

        uint afterSecond = c.tokenBalance(address(this));

        // General rule: if the first call succeeded, balance is exactly 20 and
        // the second call reverted leaving balance unchanged.
        if (!firstReverted) {
            assert(afterFirst == 20 && afterSecond == 20 && secondReverted);
        } else {
            assert(afterFirst == before && afterSecond == before);
        }
    }
}

